def format_headline(text):
    clean_text = text.strip().lower()
    if not clean_text:
        return ''
    formatted = clean_text[0].upper() + clean_text[1:]
    vowels = 'аеёиоуыэюя'
    if formatted[0].lower() in vowels:
        return formatted + '!'
    else:
        return formatted + '.'
